static void Sync(string path,Transform sceneGroup,bool main){var prefab=PrefabUtility.LoadPrefabContents(path);try{var g=main?prefab.transform.Find(Group):prefab.transform;foreach(var garden in sceneGroup.Cast<Transform>().Where(t=>t.name.StartsWith("Garden - "))){var target=g.Find(garden.name);foreach(var f in garden.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.name.StartsWith("GardenPlants_"))){var a=target.Find(f.name);a.GetComponent<MeshFilter>().sharedMesh=f.sharedMesh;}
