static void Run(string mode){var log=new StringBuilder();try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var roots=scene.GetRootGameObjects();var root=roots.Single(g=>g.name=="Track Roads");var group=root.transform.Find(Group);
if(mode=="lamps"){var candidates=roots.SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Where(f=>f.GetComponent<MeshRenderer>()&&!f.transform.IsChildOf(group)&&f.gameObject.activeInHierarchy).Where(f=>{var b=f.GetComponent<Renderer>().bounds;return b.size.y>2.5f&&b.size.y<5.6f&&Mathf.Max(b.size.x,b.size.z)<2.2f&&Mathf.Min(b.size.x,b.size.z)<.8f;}).GroupBy(f=>f.sharedMesh).Select(g=>g.First()).ToArray();int k=0;foreach(var f in candidates){var r=f.GetComponent<Renderer>();var p=r.bounds.center;Photo(scene,p+new Vector3(4,1,-4),p,"Garden-LampCandidate-"+k);log.AppendLine(k+" "+f.name+" mesh="+AssetDatabase.GetAssetPath(f.sharedMesh)+" bounds="+r.bounds);k++;}File.WriteAllText("FinalEnvironmentRoadReview/GardenLampReport.txt",log.ToString());return;}
string backup="FinalEnvironmentRoadBackup/GardenRefine-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss");Directory.CreateDirectory(backup);EditorSceneManager.SaveScene(scene,backup+"/Before.unity",true);File.Copy(Prefab,backup+"/Before.prefab");File.Copy(Out+"/"+Group+".prefab",backup+"/Before-group.prefab");
var source=roots.SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).First(f=>f.name.StartsWith("metal street props low poly.012")&&!f.transform.IsChildOf(group));var lampMesh=source.sharedMesh;var lampMats=source.GetComponent<MeshRenderer>().sharedMaterials;int total=0,lamps=0,benches=0;
foreach(var garden in group.Cast<Transform>().Where(t=>t.name.StartsWith("Garden - "))){string name=garden.name.Substring(9);var plot=root.GetComponentsInChildren<MeshFilter>(true).Single(f=>f.name==name);var surf=C("Read",plot);var bounds=plot.GetComponent<Renderer>().bounds;float width=bounds.size.x,length=bounds.size.z,min=Mathf.Min(width,length),scale=Mathf.Clamp(min/75,.65f,1);
var bt=T.GetNestedType("B",BindingFlags.NonPublic);var batches=Enumerable.Range(0,4).Select(k=>Activator.CreateInstance(bt,true)).ToArray();var random=new System.Random(name=="polySurface47"?4700:74200);int count=0;
Action<float,float,int,float,float> Add=(u,v,tile,w,h)=>{if(u<.015f||u>.985f||v<.015f||v>.985f)return;var p=(Vector3)C("PlotPoint",surf,u,v);int batch=(u>.5?1:0)+(v>.5?2:0);C("Plant",batches[batch],p,w*(.85f+(float)random.NextDouble()*.3f),h*(.85f+(float)random.NextDouble()*.25f),tile,(float)random.NextDouble()*180,false);count++;};
for(int edge=0;edge<4;edge++){float extent=edge<2?length:width;int number=Mathf.CeilToInt((extent*.82f)/1.55f);for(int j=0;j<=number;j++){float t=Mathf.Lerp(.09f,.91f,j/(float)number);for(int row=0;row<2;row++){float inset=(Mathf.Clamp(min*.032f,1.4f,2.4f)+1.25f+row*1.75f)/(edge<2?width:length);float u=edge<2?(edge==0?inset:1-inset):t,v=edge<2?t:(edge==2?inset:1-inset);u+=((float)random.NextDouble()-.5f)*.008f;v+=((float)random.NextDouble()-.5f)*.008f;Add(u,v,row==0?(j%4==0?4:5+j%2):(j%3==0?7:5+j%2),row==0?2.6f:2.3f,row==0?1.55f:1.1f);}}}
for(int sx=-1;sx<=1;sx+=2)for(int sz=-1;sz<=1;sz+=2){var dir=new Vector2(sx*width,sz*length).normalized;var normal=new Vector2(-dir.y,dir.x);float span=new Vector2(width*.34f,length*.34f).magnitude;int n=Mathf.CeilToInt(span/1.6f);for(int j=0;j<=n;j++){float t=Mathf.Lerp(.22f,.79f,j/(float)n);var point=new Vector2(sx*width*.42f*t,sz*length*.42f*t);foreach(int side in new[]{-1,1}){var pp=point+normal*side*(Mathf.Clamp(min*.058f,2.3f,4.5f)*.5f+1.3f);Add(.5f+pp.x/width,.5f+pp.y/length,j%4==0?7:5+j%2,2.45f,1.3f);}}
var bench=garden.Find("Existing bench "+sx+" "+sz);var outer=garden.Find("Existing outer bench "+sx+" "+sz);foreach(var b in new[]{bench,outer}.Where(v=>v)){float t=b==bench?.57f:.81f;var pp=new Vector2(sx*width*.42f*t,sz*length*.42f*t)+normal*(Mathf.Clamp(min*.058f,2.3f,4.5f)*.5f-.65f);var p=(Vector3)C("PlotPoint",surf,.5f+pp.x/width,.5f+pp.y/length);var r=b.GetComponent<Renderer>();b.rotation=Quaternion.Euler(0,Mathf.Atan2(-dir.y,dir.x)*Mathf.Rad2Deg,0)*Quaternion.Euler(-90,0,0);var bb=r.bounds;b.position+=new Vector3(p.x-bb.center.x,p.y-bb.min.y,p.z-bb.center.z);PrefabUtility.RecordPrefabInstancePropertyModifications(b);benches++;}}
float ring=min*.15f+1.05f;int ringCount=Mathf.CeilToInt(ring*Mathf.PI*2/1.4f);for(int j=0;j<ringCount;j++){float a=j*Mathf.PI*2/ringCount;float x=Mathf.Cos(a)*ring,z=Mathf.Sin(a)*ring;float diagonal=Mathf.Min(Mathf.Abs(x*length-z*width),Mathf.Abs(x*length+z*width))/new Vector2(width,length).magnitude;if(diagonal<Mathf.Clamp(min*.058f,2.3f,4.5f)*.5f+1)continue;Add(.5f+x/width,.5f+z/length,j%5==0?4:5+j%2,2.7f,1.4f);}
foreach(var f in garden.GetComponentsInChildren<MeshFilter>().Where(f=>f.name.StartsWith("GardenPlants_"))){int k=int.Parse(f.name.Substring(f.name.LastIndexOf('_')+1));string path=AssetDatabase.GetAssetPath(f.sharedMesh);File.Copy(path,backup+"/"+Path.GetFileName(path));var mesh=(Mesh)bt.GetMethod("Mesh").Invoke(batches[k],new object[]{f.sharedMesh.name});var colors=mesh.colors;var info=mesh.uv2;for(int j=0;j<colors.Length;j++)colors[j].a=(info[j].x+.5f)/16;mesh.colors=colors;EditorUtility.CopySerialized(mesh,f.sharedMesh);UnityEngine.Object.DestroyImmediate(mesh);EditorUtility.SetDirty(f.sharedMesh);}
foreach(var lamp in garden.Cast<Transform>().Where(t=>t.name.StartsWith("Existing ")&&t.name.Contains("lamp"))){var r=lamp.GetComponent<MeshRenderer>();var p=r.bounds.center;float baseY=r.bounds.min.y;lamp.GetComponent<MeshFilter>().sharedMesh=lampMesh;r.sharedMaterials=lampMats;lamp.rotation=source.transform.rotation;lamp.localScale=source.transform.lossyScale;var b=r.bounds;lamp.position+=new Vector3(p.x-b.center.x,baseY-b.min.y,p.z-b.center.z);PrefabUtility.RecordPrefabInstancePropertyModifications(lamp);PrefabUtility.RecordPrefabInstancePropertyModifications(lamp.GetComponent<MeshFilter>());PrefabUtility.RecordPrefabInstancePropertyModifications(r);lamps++;}
total+=count;log.AppendLine(name+" planting clumps="+count);}
foreach(var garden in group.Cast<Transform>().Where(t=>t.name.StartsWith("Garden - ")))typeof(FinalAtlasGardenFinish).GetMethod("Canopies",Flags).Invoke(null,new object[]{garden.gameObject});foreach(var f in group.GetComponentsInChildren<MeshFilter>().Where(f=>f.name.StartsWith("GardenPlants_"))){var colors=f.sharedMesh.colors;var info=f.sharedMesh.uv2;for(int j=0;j<colors.Length;j++)colors[j].a=(info[j].x+.5f)/16;f.sharedMesh.colors=colors;var garden=f.transform.parent;string plotName=garden.name.Substring(9);var plotBounds=root.GetComponentsInChildren<MeshRenderer>().Single(r=>r.name==plotName).bounds;f.sharedMesh.SetUVs(3,Enumerable.Repeat(new Vector2(plotBounds.size.x,plotBounds.size.z),f.sharedMesh.vertexCount).ToList());f.sharedMesh.SetUVs(4,f.sharedMesh.vertices.Select(v=>{var p=f.transform.TransformPoint(v);return new Vector2((p.x-plotBounds.min.x)/plotBounds.size.x,(p.z-plotBounds.min.z)/plotBounds.size.z);}).ToList());EditorUtility.SetDirty(f.sharedMesh);}
AssetDatabase.SaveAssets();Sync(Prefab,group,true);Sync(Out+"/"+Group+".prefab",group,false);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);
foreach(string name in new[]{"polySurface47","polySurface742"}){var r=root.GetComponentsInChildren<MeshRenderer>().Single(v=>v.name==name);var p=r.bounds.center;float size=Mathf.Max(r.bounds.size.x,r.bounds.size.z);Photo(scene,p+new Vector3(size*.22f,size*.64f,-size*.45f),p,"Refined-"+name);Photo(scene,p+new Vector3(12,6,-15),p+new Vector3(5,1,-12),"Refined-"+name+"-Detail");var entrance=p+new Vector3(r.bounds.size.x*.40f,0,r.bounds.size.z*.40f);Photo(scene,entrance+Vector3.up*15,entrance,"Trimmed-"+name+"-Entrance");}
var mat=AssetDatabase.LoadAssetAtPath<Material>(Out+"/City Garden Utility Atlas.mat");int errors=ShaderUtil.GetShaderMessages(mat.shader).Count(v=>v.severity.ToString()=="Error");if(errors>0)throw new Exception("Shader errors="+errors);log.AppendLine("SUCCESS plants="+total+" benches="+benches+" replacement lamps="+lamps+"; two gardens and both prefabs saved; shader errors=0; wind retained; no added realtime lights; shared atlas reused; backup="+backup);
}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/GardenRefineReport.txt",log.ToString());}}

